// Makes a second-pass reel from a built reel: same scenes, same beats, same voices and effects — only the pictures
// that have a retake are repointed, everything else still points at the first pass.
//
//   node tools/retake-reel-pictures.mjs hangar [--dry]
//
// Reads src/data/hangarColdOpenReel.ts (generated by tools/build-playframe-reel.mjs from PlayFrame — never hand-edit
// that file), looks for each picture it uses by file name under public/reels/hangar/img/hangar-v2/ (any sub-folder:
// shots/, sheets/, key-art), and writes src/data/hangarColdOpenV2Reel.ts with those paths swapped in, under its own
// story id and title. The first pass stays exactly as it is, so the two can be played side by side.
//
// The retakes themselves live in public/reels/hangar/img/hangar-v2/ and keep the first pass's file names, so this
// stays a pure path swap: re-run it after any new picture lands and the second-pass reel picks it up. It prints
// what is still missing (the first-pass picture that beat will keep showing).
//
// Generated output: change the storyboard in PlayFrame, or the retake, not src/data/hangarColdOpenV2Reel.ts.
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, relative, resolve } from "node:path";

const root = process.cwd();
const args = process.argv.slice(2);
const which = args.find(a => !a.startsWith("--"));
const DRY = args.includes("--dry");

const CONFIG = {
  hangar: {
    source: "src/data/hangarColdOpenReel.ts",
    out: "src/data/hangarColdOpenV2Reel.ts",
    export: "HANGAR_COLD_OPEN_V2_REEL",
    id: "hangar-cold-open-v2-reel",
    title: "Untitled: the cold open — second pass (work in progress)",
    tagline:
      "The same cold open, redrawn: late-1990s cel animation, painted backgrounds and the 2.39:1 frame, in place of the painted boards. Work in progress — a shot with no retake yet still shows its first-pass picture.",
    artRoot: "public/reels/hangar/img/hangar-v2",
    // where a retake of each kind of picture is looked for (sub-folder under artRoot). key-art is any folder.
    folders: { "/reels/hangar/img/hangar/": "shots", "/reels/hangar/img/hangar/sheets/": "" },
    portraits: "/reels/hangar/img/portraits/hangar/sheets/",
    portraitsRetake: "public/reels/hangar/img/portraits/hangar-v2/sheets",
  },
};

if (!which || !CONFIG[which]) {
  console.error("usage: node tools/retake-reel-pictures.mjs hangar [--dry]");
  process.exit(1);
}
const cfg = CONFIG[which];

/** Every .jpg under artRoot, by file name, with its public URL. */
function scanRetakes(dir) {
  const out = new Map();
  if (!existsSync(dir)) return out;
  const walk = d => {
    for (const name of readdirSync(d)) {
      const p = join(d, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (/\.(jpe?g|png|webp)$/i.test(name) && !out.has(name)) out.set(name, "/" + relative(join(root, "public"), p).split("\\").join("/"));
    }
  };
  walk(dir);
  return out;
}

const retakes = scanRetakes(resolve(root, cfg.artRoot));
const portraitDir = resolve(root, cfg.portraitsRetake);
const portraitRetakes = scanRetakes(portraitDir);

const sourceText = readFileSync(resolve(root, cfg.source), "utf8");
const match = sourceText.match(/export const \w+: Story = (\{[\s\S]*\}) as unknown as Story;/);
if (!match) {
  console.error(`${cfg.source}: could not find the story object — rebuild the reel first`);
  process.exit(1);
}
const story = JSON.parse(match[1]);

const used = new Set();
const missing = new Map();
let swapped = 0;
const swappedKeys = new Set();

/** Point one picture path at its retake, if there is one. */
function retakePath(oldPath, isPortrait = false) {
  if (!oldPath) return oldPath;
  used.add(oldPath);
  const name = oldPath.split("/").pop();
  const table = isPortrait ? portraitRetakes : retakes;
  const hit = table.get(name);
  if (hit) {
    const key = hit + "|" + isPortrait;
    if (!swappedKeys.has(key)) { swappedKeys.add(key); swapped++; }
    return hit;
  }
  if (!missing.has(name)) missing.set(name, oldPath);
  return oldPath;
}

for (const scene of story.scenes) {
  scene.background = retakePath(scene.background);
  for (const beat of scene.dialogueBeats || []) {
    beat.background = retakePath(beat.background);
    if (beat.foregroundImage) beat.foregroundImage = retakePath(beat.foregroundImage);
  }
  for (const spot of scene.hotspots || []) if (spot.background) spot.background = retakePath(spot.background);
}
for (const ch of story.characters || []) {
  if (ch.avatarUrl && ch.avatarUrl.startsWith(cfg.portraits)) ch.avatarUrl = retakePath(ch.avatarUrl, true);
}

story.id = cfg.id;
story.title = cfg.title;
story.tagline = cfg.tagline;
// A fingerprint of the retakes in play (not a date), so the file only changes when the art does.
const stamp = createHash("sha1");
for (const [name, url] of [...retakes]) stamp.update(name + ":" + url);
story.builtinRevision = "retake-" + stamp.digest("hex").slice(0, 10) + "-" + (story.builtinRevision || "first-pass").split("+").pop();

const outText =
  `// GENERATED by tools/retake-reel-pictures.mjs ${which} — the first-pass reel (${cfg.source}) with every picture that\n` +
  `// has a retake under ${cfg.artRoot}/ repointed at it. Change the retake or the reel, not this file.\n` +
  `import type { Story } from "../types";\n\n` +
  `export const ${cfg.export}: Story = ${JSON.stringify(story)} as unknown as Story;\n`;

const total = used.size;
const keep = total - missing.size;
console.log(`${which}: ${swapped} picture reference(s) repointed, ${missing.size} of ${total} still first-pass`);
if (missing.size) {
  console.log("still first-pass (add the retake under " + cfg.artRoot + "/ and re-run):");
  for (const [name, path] of [...missing].sort()) console.log(`  ${name.padEnd(36)} ${path}`);
}
if (DRY) {
  console.log("--dry: not written");
} else {
  mkdirSync(resolve(root, cfg.out).replace(/\/[^/]+$/, ""), { recursive: true });
  writeFileSync(resolve(root, cfg.out), outText);
  console.log(`wrote ${cfg.out} (${keep}/${total} picture files redrawn)`);
}
